{"source":"#include <stdio.h>
#define max 100

int comp(const void*a,const void*b)
{
    return *(int*)b-*(int*)a;
}

int main(int argc, char *argv[])
{
    int n,k;
    int pile[max]={0},pilecopy[max]={0};
    int i=0,j=0,t=0,tall=0;

    scanf("%d%d",&n,&k);
    for(i=0;i<n;i++){
        scanf("%d",&pile[i]);
        pilecopy[i]=pile[i];
    }

    qsort(pile,n,sizeof(int),comp);
    for(i=n-1;i>0;i--){
        if(pile[i-1]>pile[i])
            break;
    }
    tall=pile[i]+1;
    if(pile[0]-tall+1>k){
        printf("NO\n");
        return 0;
    }
    else{
        printf("YES\n");
        for(i=0;i<n;i++){
            if(pilecopy[i]<=tall){
                for(j=0;j<pilecopy[i];j++)
                    printf("1 ");
            }
            else{
                for(j=0;j<tall;j++)
                    printf("1 ");
                t=2;
                for(j=tall;j<pilecopy[i];j++){
                    printf("%d ",t++);
                }
            }
            printf("\n");
        }
    }

    return 0;
}"}
